6	import { describe, expect, test } from 'vitest';
7	import { Emitter } from '../../../../util/vs/base/common/event';
8	import { IAuthenticationService } from '../../../authentication/common/authentication';
9	import { TestLogService } from '../../../testing/common/testLogService';
10	import { ChatQuotaService } from '../../common/chatQuotaServiceImpl';
11	
12	function createMockAuthService(): IAuthenticationService {
13		return {
14			_serviceBrand: undefined,
15			copilotToken: undefined,
16			onDidAuthenticationChange: new Emitter().event,
17		} as unknown as IAuthenticationService;
18	}
19	
20	function createMockAuthServiceWithEmitter(opts?: { isFreeUser?: boolean }) {
21		const emitter = new Emitter<void>();
22		const authService = {
23			_serviceBrand: undefined,
24			copilotToken: undefined as { isFreeUser: boolean; quotaInfo: ReturnType<typeof makeQuotaInfo> } | undefined,
25			onDidAuthenticationChange: emitter.event,
26		} as unknown as IAuthenticationService;
27		return {
28			authService, emitter, setToken: (quotaInfo: ReturnType<typeof makeQuotaInfo>) => {
29				(authService as any).copilotToken = { isFreeUser: opts?.isFreeUser ?? false, quotaInfo };
30			}
31		};
32	}
33	
34	function makeQuotaInfo(overrides: { chat?: Partial<SnapshotData>; premium_interactions?: Partial<SnapshotData> } = {}, resetDate = '2026-06-01T00:00:00Z') {
35		return {
36			quota_reset_date: resetDate,
37			quota_snapshots: {
38				chat: { quota_id: 'chat', entitlement: 100, remaining: 50, unlimited: false, overage_count: 0, overage_permitted: false, percent_remaining: 50, ...overrides.chat },
39				completions: { quota_id: 'completions', entitlement: 100, remaining: 100, unlimited: false, overage_count: 0, overage_permitted: false, percent_remaining: 100 },
40				premium_interactions: { quota_id: 'premium', entitlement: 500, remaining: 400, unlimited: false, overage_count: 5, overage_permitted: true, percent_remaining: 80, ...overrides.premium_interactions },
41			},
42		};
43	}
44	
45	type SnapshotData = { quota_id: string; entitlement: number; remaining: number; unlimited: boolean; overage_count: number; overage_permitted: boolean; percent_remaining: number };
46	
47	describe('ChatQuotaService', () => {
48		function create() {
49			return new ChatQuotaService(createMockAuthService(), new TestLogService());
50		}
51	
52		const TURN_A = 'turn-a';
53		const TURN_B = 'turn-b';
54	
55		describe('setLastCopilotUsage', () => {
56			test('converts nano-AIUs to AIC credits', () => {
57				const svc = create();
58				svc.setLastCopilotUsage(1_000_000_000, TURN_A); // 1 AIC
59				expect(svc.getCreditsForTurn(TURN_A)).toBe(1);
60			});
61	
62			test('handles fractional AIC values', () => {
63				const svc = create();
64				svc.setLastCopilotUsage(500_000_000, TURN_A); // 0.5 AIC
65				expect(svc.getCreditsForTurn(TURN_A)).toBe(0.5);
66			});
67	
68			test('accumulates across multiple calls', () => {
69				const svc = create();
70				svc.setLastCopilotUsage(300_000_000, TURN_A); // 0.3 AIC
71				svc.setLastCopilotUsage(200_000_000, TURN_A); // 0.2 AIC
72				expect(svc.getCreditsForTurn(TURN_A)).toBeCloseTo(0.5);
73			});
74	
75			test('accumulates many small calls correctly', () => {
76				const svc = create();
77				// Simulate 5 gpt-4o-mini calls at ~0.02 AIC each
78				for (let i = 0; i < 5; i++) {
79					svc.setLastCopilotUsage(16_470_000, TURN_A);
80				}
81				// Plus 2 Claude calls at ~25 AIC each
82				svc.setLastCopilotUsage(24_782_500_000, TURN_A);
83				svc.setLastCopilotUsage(25_580_500_000, TURN_A);
84				expect(svc.getCreditsForTurn(TURN_A)).toBeCloseTo(50.45);
85			});
86	
87			test('ignores zero nano-AIU values', () => {
88				const svc = create();
89				svc.setLastCopilotUsage(0, TURN_A);
90				expect(svc.getCreditsForTurn(TURN_A)).toBeUndefined();
91			});
92	
93			test('ignores negative nano-AIU values', () => {
94				const svc = create();
95				svc.setLastCopilotUsage(-100, TURN_A);
96				expect(svc.getCreditsForTurn(TURN_A)).toBeUndefined();
97			});
98	
99			test('does not accumulate zero after valid value', () => {
100				const svc = create();
101				svc.setLastCopilotUsage(1_000_000_000, TURN_A);
102				svc.setLastCopilotUsage(0, TURN_A);
103				expect(svc.getCreditsForTurn(TURN_A)).toBe(1);
104			});
105		});
106	
107		describe('resetTurnCredits', () => {
108			test('resets accumulated credits to undefined', () => {
109				const svc = create();
110				svc.setLastCopilotUsage(1_000_000_000, TURN_A);
111				expect(svc.getCreditsForTurn(TURN_A)).toBe(1);
112				svc.resetTurnCredits(TURN_A);
113				expect(svc.getCreditsForTurn(TURN_A)).toBeUndefined();
114			});
115	
116			test('allows fresh accumulation after reset', () => {
117				const svc = create();
118				svc.setLastCopilotUsage(1_000_000_000, TURN_A);
119				svc.resetTurnCredits(TURN_A);
120				svc.setLastCopilotUsage(500_000_000, TURN_A);
121				expect(svc.getCreditsForTurn(TURN_A)).toBe(0.5);
122			});
123	
124			test('is idempotent when already undefined', () => {
125				const svc = create();
126				svc.resetTurnCredits(TURN_A);
127				expect(svc.getCreditsForTurn(TURN_A)).toBeUndefined();
128			});
129		});
130	
131		describe('concurrent turn isolation', () => {
132			test('credits for different turns are independent', () => {
133				const svc = create();
134				svc.setLastCopilotUsage(1_000_000_000, TURN_A);
135				svc.setLastCopilotUsage(2_000_000_000, TURN_B);
136				expect(svc.getCreditsForTurn(TURN_A)).toBe(1);
137				expect(svc.getCreditsForTurn(TURN_B)).toBe(2);
138			});
139	
140			test('resetting one turn does not affect another', () => {
141				const svc = create();
142				svc.setLastCopilotUsage(1_000_000_000, TURN_A);
143				svc.setLastCopilotUsage(2_000_000_000, TURN_B);
144				svc.resetTurnCredits(TURN_A);
145				expect(svc.getCreditsForTurn(TURN_A)).toBeUndefined();
146				expect(svc.getCreditsForTurn(TURN_B)).toBe(2);
147			});
148	
149			test('subagent credits accumulate into the parent turn', () => {
150				const svc = create();
151				// Main agent call
152				svc.setLastCopilotUsage(1_000_000_000, TURN_A);
153				// Subagent call attributed to same turn
154				svc.setLastCopilotUsage(500_000_000, TURN_A);
155				expect(svc.getCreditsForTurn(TURN_A)).toBe(1.5);
156			});
157		});
158	
159		describe('realistic turn lifecycle simulation', () => {
160			/**
161			 * Simulates a single LLM API call in a turn, with a delay to model
162			 * real async timing (network latency, streaming, etc.)
163			 */
