20	export abstract class BaseCAPIClientService extends CAPIClient implements ICAPIClientService {
21		readonly _serviceBrand: undefined;
22		public abExpContext: string | undefined;
23	
24		constructor(
25			hmac: string | undefined,
26			integrationId: string | undefined,
27			fetcherService: IFetcherService,
28			envService: IEnvService
29		) {
30			super({
31				machineId: envService.machineId,
32				deviceId: envService.devDeviceId,
33				sessionId: envService.sessionId,
34				vscodeVersion: envService.vscodeVersion,
35				buildType: envService.getBuildType(),
36				name: envService.getName(),
37				version: envService.getVersion(),
38			}, LICENSE_AGREEMENT, fetcherService, hmac, integrationId);
39		}
