41		override makeRequest<T>(request: MakeRequestOptions, requestMetadata: RequestMetadata): Promise<T> {
42			// Inject AB Exp Context headers (legacy VScode-ABExpContext and new standardized X-Copilot-Client-Exp-Assignment-Context) if available
43			if (this.abExpContext) {
44				if (!request.headers) {
45					request.headers = {};
46				}
47				request.headers['VScode-ABExpContext'] = this.abExpContext;
48				request.headers['X-Copilot-Client-Exp-Assignment-Context'] = this.abExpContext;
49			}
50			// Expected high request volume events that we don't need to collect fetch telemetry for
51			if (
52				requestMetadata.type === RequestType.Telemetry ||
53				requestMetadata.type === RequestType.ChatCompletions ||
54				requestMetadata.type === RequestType.ChatMessages ||
55				requestMetadata.type === RequestType.ChatResponses
56			) {
57				request.callSite = NO_FETCH_TELEMETRY;
58			}
59			return super.makeRequest<T>(request, requestMetadata);
60		}
61	}
