7	import { IAuthenticationService } from '../../../platform/authentication/common/authentication';
8	import { IChatQuota, IChatQuotaService } from '../../../platform/chat/common/chatQuotaService';
9	import { Disposable } from '../../../util/vs/base/common/lifecycle';
10	
11	const QUOTA_NOTIFICATION_ID = 'copilot.quotaStatus';
12	const THRESHOLDS = [50, 75, 90, 95];
13	
14	interface IRateLimitWarning {
15		percentUsed: number;
16		type: 'session' | 'weekly';
17		resetDate: Date;
18	}
19	
20	interface IQuotaWarning {
21		percentUsed: number;
22		resetDate: Date;
23	}
